import{_ as t,o,c as d,ax as a}from"./chunks/framework.D0-oyZN4.js";const g=JSON.parse('{"title":"Command Reference","description":"Every Developer Studio CLI command, its flags, and its exit behavior.","frontmatter":{"description":"Every Developer Studio CLI command, its flags, and its exit behavior."},"headers":[],"relativePath":"cli/reference/commands.md","filePath":"cli/reference/commands.md"}'),s={name:"cli/reference/commands.md"};function n(r,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/commands.md for this page in Markdown format</div><h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Documents every <code>gsds</code> subcommand at version <code>1.8.2</code>. Every command exits <code>0</code> on success and <code>1</code> on any failure, and <code>130</code> when you interrupt it with <code>Ctrl-C</code>. Only <code>gsds preview</code> and <code>gsds connector test</code> require an active session.</p><h2 id="gsds-init" tabindex="-1"><code>gsds init</code> <a class="header-anchor" href="#gsds-init" aria-label="Permalink to &quot;`gsds init`&quot;">​</a></h2><p>Scaffolds a new project, or backfills missing files into an existing widget project. Writes only whatever&#39;s missing — <code>gsds.json</code>, <code>extensions_registry.json</code>, <code>connectors_registry.json</code>, <code>AGENTS.md</code>, <code>README.md</code>, and a <code>.gitignore</code> that excludes <code>.gsds/</code> — and never overwrites a file it finds. A <code>gsds.json</code> that predates shared-dependency deduplication (no <code>dedupe</code> key at all) gets <code>@angular/*</code> backfilled into its exclude list automatically; a <code>gsds.json</code> that already has a <code>dedupe</code> key, even an empty one, is left untouched. It also refreshes <code>gsds.json</code>&#39;s <code>cliVersion</code> to the version of <code>gsds</code> you are running, reporting <code>Updated gsds.json cliVersion 1.5.0 -&gt; 1.8.0.</code> — this is what clears the stale-version notice every other command prints while that field is behind.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Yes</td><td>Directory to create or reuse. Pass <code>.</code> to scaffold the current directory in place — the project name falls back to the directory&#39;s own name</td></tr><tr><td><code>--force</code></td><td>No</td><td>Allow scaffolding into a non-empty directory that isn&#39;t recognized as an existing widget project (see below)</td></tr></tbody></table><h3 id="when-you-need-force-—-and-when-you-don-t" tabindex="-1">When you need <code>--force</code> — and when you don&#39;t <a class="header-anchor" href="#when-you-need-force-—-and-when-you-don-t" aria-label="Permalink to &quot;When you need `--force` — and when you don&#39;t&quot;">​</a></h3><p><code>gsds init</code> recognizes an existing widget project automatically, with no flag, when the target directory already has any of:</p><ul><li><code>extensions_registry.json</code></li><li><code>connectors_registry.json</code></li><li><code>gsds.json</code></li><li>the legacy <code>widget_registry.json</code> — migrated to <code>extensions_registry.json</code> automatically, content preserved byte-for-byte</li></ul><p>This covers the common case of an existing repo: one cloned or forked from the <a href="https://github.com/gainsight-hub/widgets-repository-template" target="_blank" rel="noreferrer">Widgets Repository Template</a>, or any project already using <code>gsds</code>. Re-running <code>gsds init</code> against it backfills only what&#39;s missing (for example a <code>gsds.json</code> a template clone never had) and leaves every existing file untouched.</p><p><code>--force</code> is only for a non-empty directory with <strong>none</strong> of the markers above — for example a freshly created GitHub repo with just a <code>README.md</code> or <code>LICENSE</code> from the &quot;initialize this repository&quot; checkbox. <code>--force</code> means &quot;I know this directory is safe to scaffold into&quot;; it does not relax the never-overwrite guarantee, and it is not the default answer to &quot;I already have a repo&quot; — most existing widget repos already carry one of the markers above and need no flag at all. A bare <code>widgets/</code> directory by itself does not count as a marker: it&#39;s too generic a signal (design assets, an unrelated monorepo subfolder) to prove a widget project on its own.</p><h2 id="gsds-login" tabindex="-1"><code>gsds login</code> <a class="header-anchor" href="#gsds-login" aria-label="Permalink to &quot;`gsds login`&quot;">​</a></h2><p>Redeems a pairing code, reports the current session, or does nothing when no arguments are provided. Each tenant you log into is kept as its own profile; the one you just logged into becomes current.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;pairing_code&gt;</code></td><td>Redeem a pairing code from <strong>Integrations → Developer Studio → CLI Access</strong> in the community. Codes expire 1 minute after issue</td></tr><tr><td><code>--status</code></td><td>Print the current session&#39;s tenant binding and validity</td></tr><tr><td><code>--profile &lt;name&gt;</code></td><td>Store the resulting session under an explicit profile name instead of the tenant-derived default</td></tr></tbody></table><p>The resulting session lasts 8 hours and is tenant-scoped. There is no refresh flow.</p><p>A <code>--profile</code> value is trimmed of surrounding whitespace and capped at 96 characters. An empty or whitespace-only value is rejected before the pairing code is redeemed, so a mistyped flag does not burn the single-use code.</p><h2 id="gsds-logout" tabindex="-1"><code>gsds logout</code> <a class="header-anchor" href="#gsds-logout" aria-label="Permalink to &quot;`gsds logout`&quot;">​</a></h2><p>Clears the stored session for the current profile. No flags besides <code>--profile &lt;name&gt;</code>, which clears a specific profile&#39;s session instead of the current one.</p><p>When other profiles remain, <code>gsds logout</code> promotes one to current and prints <code>&lt;name&gt; is now the current profile.</code> It prefers a profile that is neither expired nor unreadable. When only an unusable one is left, it says so on its own line:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>That session needs a new login - run `gsds login &lt;pairing_code&gt;`.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="gsds-profile" tabindex="-1"><code>gsds profile</code> <a class="header-anchor" href="#gsds-profile" aria-label="Permalink to &quot;`gsds profile`&quot;">​</a></h2><p>Lists stored login profiles, marks the current one, and marks any that need a new login.</p><p>Each row is the profile name followed, in parentheses, by whatever applies: <code>current</code>, <code>expired</code> when its stored session has timed out, and <code>unreadable</code> when its stored credential cannot be read. An expired profile stays stored and stays switchable — it is the name to log back in under.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>acme-en (current)</span></span>\n<span class="line"><span>acme-eu (expired)</span></span>\n<span class="line"><span>acme-sandbox (unreadable)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--json</code></td><td>Emit the profile list as machine-readable JSON instead of a table. Each row carries <code>profile</code>, <code>tenant</code>, <code>current</code>, <code>expired</code>, and <code>unreadable</code></td></tr></tbody></table><h3 id="gsds-profile-use-name" tabindex="-1"><code>gsds profile use &lt;name&gt;</code> <a class="header-anchor" href="#gsds-profile-use-name" aria-label="Permalink to &quot;`gsds profile use &lt;name&gt;`&quot;">​</a></h3><p>Switches which stored profile is current. Every subsequent command that needs a session (<code>preview</code>, <code>logout</code>, <code>connector test</code>) uses this profile automatically until you switch again. The name is matched case-insensitively and ignores surrounding whitespace.</p><h2 id="gsds-create" tabindex="-1"><code>gsds create</code> <a class="header-anchor" href="#gsds-create" aria-label="Permalink to &quot;`gsds create`&quot;">​</a></h2><p>Scaffolds a widget under <code>widgets/&lt;name&gt;/</code>. Interactive in a <strong>TTY</strong> (a terminal a person is typing into); in a non-TTY session (CI, an AI agent) the three flags below are required and the command fails fast when any is missing.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Required (non-TTY)</th><th>Description</th></tr></thead><tbody><tr><td><code>--name</code></td><td>Yes</td><td>Widget slug</td></tr><tr><td><code>--framework</code></td><td>Yes</td><td>One of <code>react</code>, <code>vue</code>, <code>angular</code>, <code>vanilla</code>, <code>html</code>. Case-insensitive</td></tr><tr><td><code>--category</code></td><td>Yes</td><td>Category label used in the No-Code Builder</td></tr></tbody></table><p><code>gsds create</code> writes no <code>widget.json</code>. The new widget exists only as an entry appended to <code>extensions_registry.json</code>, in the same shape a hand-authored widget has. Appending holds a lock on the registry file while it writes, so parallel <code>gsds create</code> runs cannot drop each other&#39;s entries.</p><p>It then runs an incremental build so that a dependency the new widget now shares with another widget is pulled out of both bundles straight away — only the new widget, plus any widget whose shared dependencies actually changed, not every widget in the project. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>.</p><h2 id="gsds-list" tabindex="-1"><code>gsds list</code> <a class="header-anchor" href="#gsds-list" aria-label="Permalink to &quot;`gsds list`&quot;">​</a></h2><p>Lists Extensions in the current project.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--json</code></td><td>Emit a keyed object <code>{ widgets, connectors, scripts, stylesheets }</code> instead of a table. Not a bare array. The stale-<code>cliVersion</code> notice goes to stderr, so stdout stays valid JSON</td></tr></tbody></table><h2 id="gsds-preview" tabindex="-1"><code>gsds preview</code> <a class="header-anchor" href="#gsds-preview" aria-label="Permalink to &quot;`gsds preview`&quot;">​</a></h2><p>Boots a local dev server, registers a preview session with the paired community, and makes local widgets appear in the No-Code Builder picker.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--port</code></td><td>Override the preview port. Default <code>5173</code></td></tr><tr><td><code>--widget &lt;name&gt;</code></td><td>Restrict the preview to specific widgets. Repeatable</td></tr><tr><td><code>--profile &lt;name&gt;</code></td><td>Preview using a specific stored profile instead of the current one</td></tr></tbody></table><p>Requires an active session, paired under the same account you sign in to your community with — the No-Code Builder looks for a preview session belonging to the account you are signed in as.</p><p>A widget appears in the picker if it declares a <code>dev</code> script in its <code>package.json</code>, or — with no <code>dev</code> script — its registry entry declares a <code>source</code>, in which case the preview server serves it directly. A widget with neither is skipped, and <code>gsds preview</code> names it. For a widget that does have a <code>dev</code> script, the package manager is resolved from that widget&#39;s <code>package.json</code> <code>packageManager</code> field first, and from its lockfile when that field is absent.</p><p>For a widget served as static HTML, asset references resolve the way publishing resolves them: a root-absolute reference such as <code>/app.js</code> resolves against the widget root, and a reference naming no file in the widget is left exactly as written, with a one-time warning so a typo stays visible.</p><p>Preview serves from <code>http://localhost:&lt;port&gt;</code>, and each JavaScript widget&#39;s own <code>dev</code> script serves from a further port of its own — HTML-only widgets add none. Your community page loads from all of them directly, which needs a browser permission the first time. See <a href="./troubleshooting.html#the-browser-blocks-the-local-preview">Troubleshooting</a>.</p><h2 id="gsds-build" tabindex="-1"><code>gsds build</code> <a class="header-anchor" href="#gsds-build" aria-label="Permalink to &quot;`gsds build`&quot;">​</a></h2><p>Builds each widget, then validates and normalizes <code>extensions_registry.json</code> and <code>connectors_registry.json</code> in place.</p><p>Both registries are <strong>hand-authored sources of truth</strong>, not generated output. <code>gsds build</code> never derives widget entries from a scan of <code>widgets/</code>, and a widget with no registry entry is invisible in your community. Field order, array order, and top-level keys <code>gsds</code> does not manage are all preserved, so a build with nothing to change produces no diff.</p><p>A widget&#39;s <code>type</code> is the identifier the platform uses to match a widget already placed on a community page to its source. <code>gsds build</code> leaves it exactly as the registry declares it, and never derives it from the folder name.</p><p>Normalizing writes only the parts <code>gsds</code> manages: the <code>importMaps</code> entries for shared dependencies, and dropping a <code>scripts</code> or <code>stylesheets</code> key once its last entry is removed. Everything you wrote is left as you wrote it.</p><p>Installs each widget&#39;s dependencies automatically first (concurrently) if missing — no manual <code>npm install</code> needed per widget. A widget whose install fails is left out of the rebuild pass, and the build then fails, naming every widget it could not prepare.</p><p>Every widget entry in <code>extensions_registry.json</code> must declare a non-empty <code>title</code> and <code>category</code>, or the build fails and names the offending entry.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--validate</code></td><td>Check that every registry entry still resolves to the files it names, and exit <code>1</code> on drift. Does not rebuild <code>dist/</code>. Intended as a CI gate</td></tr></tbody></table><p>Registry writes take the same lock, one writer at a time, so parallel <code>gsds build</code>, <code>gsds create</code>, and <code>gsds script new</code> runs cannot drop each other&#39;s entries.</p><h3 id="files-gsds-build-ignores" tabindex="-1">Files <code>gsds build</code> ignores <a class="header-anchor" href="#files-gsds-build-ignores" aria-label="Permalink to &quot;Files `gsds build` ignores&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What <code>gsds build</code> finds</th><th>What it means</th></tr></thead><tbody><tr><td><code>widget.json</code> or <code>connectors.json</code> inside a widget that <strong>is</strong> in <code>extensions_registry.json</code></td><td>Redundant — the widget is already declared in the registry. Safe to delete</td></tr><tr><td><code>widget.json</code> inside a widget that is <strong>not</strong> in <code>extensions_registry.json</code></td><td>That file is the widget&#39;s only remaining metadata. Migrate it into the registry — deleting it loses the widget</td></tr><tr><td>A <code>widgets/&lt;name&gt;/</code> folder with no registry entry</td><td>The platform will never see it. Add an entry, or delete the folder if it is not a widget</td></tr></tbody></table><h3 id="missing-registries" tabindex="-1">Missing registries <a class="header-anchor" href="#missing-registries" aria-label="Permalink to &quot;Missing registries&quot;">​</a></h3><p>A registry file absent from a project that already had one is refused, not rebuilt from scratch: the file is the source of truth, so rebuilding cannot recover what it held. Restore it from version control. See <a href="./troubleshooting.html#a-registry-file-is-missing">Troubleshooting</a>.</p><h3 id="what-else-gsds-build-refuses" tabindex="-1">What else <code>gsds build</code> refuses <a class="header-anchor" href="#what-else-gsds-build-refuses" aria-label="Permalink to &quot;What else `gsds build` refuses&quot;">​</a></h3><p>Each of these fails the build and names what it found.</p><table tabindex="0"><thead><tr><th>Condition</th><th>What it means</th></tr></thead><tbody><tr><td>Two widget entries declaring the same <code>type</code></td><td>The <code>type</code> no longer identifies one widget. A duplicate Connector permalink fails the same way</td></tr><tr><td>An entry whose <code>source</code> block is incomplete, or whose <code>source.path</code> points outside its own <code>widgets/&lt;name&gt;/</code> folder</td><td>The entry does not resolve to files belonging to that widget</td></tr><tr><td>A widget whose <code>package.json</code> is not valid JSON</td><td>The widget&#39;s build step cannot be read</td></tr><tr><td>A <code>gsds.json</code> that is not valid JSON, or not the expected shape</td><td><code>dedupe.exclude</code> cannot be read, so which packages are excluded from deduplication is unknown</td></tr><tr><td>A registry file that is a symlink, or that is read-only</td><td>Writing publishes through a rename, which replaces the path itself: a symlink would be deleted rather than followed, and a read-only file would be replaced regardless of the permission set on it</td></tr></tbody></table><h3 id="shared-dependency-deduplication" tabindex="-1">Shared dependency deduplication <a class="header-anchor" href="#shared-dependency-deduplication" aria-label="Permalink to &quot;Shared dependency deduplication&quot;">​</a></h3><p>Any package declared in two or more widgets&#39; <code>package.json</code> <code>dependencies</code> is externalized out of those widgets&#39; bundles automatically, and the registry gets an <code>importMaps</code> entry so the browser loads one shared copy. <code>--validate</code> also checks <code>importMaps</code> for drift when every shared dependency&#39;s version can be resolved without installing anything; otherwise it skips that comparison rather than false-failing. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a> for the full mechanics, exclusions, and version-conflict rules.</p><h2 id="gsds-connector-test" tabindex="-1"><code>gsds connector test</code> <a class="header-anchor" href="#gsds-connector-test" aria-label="Permalink to &quot;`gsds connector test`&quot;">​</a></h2><p>Runs a Connector against the paired tenant. Resolution is local-first in two steps — <code>connectors_registry.json</code>, the root file the platform ingests, then the Connector persisted on the tenant — and every run reports which of the two won.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>[name]</code></td><td>Connector to run. Resolution is local-first, in order: <code>connectors_registry.json</code>, then the tenant</td></tr><tr><td><code>--payload @&lt;file&gt;</code></td><td>Path to a JSON file containing the request body. File reference only — inline JSON is rejected</td></tr><tr><td><code>--query k=v</code></td><td>Query parameter. Repeatable</td></tr><tr><td><code>--path-param k=v</code></td><td>Path parameter. Repeatable</td></tr><tr><td><code>--verbose</code></td><td>Print the rendered upstream request</td></tr><tr><td><code>--json</code></td><td>Emit a machine-readable result</td></tr><tr><td><code>--profile &lt;name&gt;</code></td><td>Run against a specific stored profile instead of the current one</td></tr></tbody></table><p>Requires an active session. Composite Connectors cannot be tested.</p><p>The <code>source:</code> line prints before the request goes out. A local match states a fact; the tenant step can only state an intent, and reads <code>source: no local definition - trying a connector persisted on your tenant</code>. When neither holds the name, the failure reads <code>Connector &quot;x&quot; is not defined in this project, and your tenant has no persisted connector under that name.</code></p><p>Every run is captured under <code>.gsds/</code> with sensitive headers redacted.</p><h2 id="gsds-update" tabindex="-1"><code>gsds update</code> <a class="header-anchor" href="#gsds-update" aria-label="Permalink to &quot;`gsds update`&quot;">​</a></h2><p>Checks the npm registry for a newer CLI version now, and installs it after you confirm.</p><p>No flags. In a non-TTY shell (or with <code>CI=true</code>), it prints the <code>npm install -g</code> command instead of running it, and exits <code>0</code> without installing. This is also the only way to take a major-version or prerelease upgrade — <code>gsds</code>&#39;s automatic background check (see <a href="./../automate-with-ci-and-ai.html#control-the-automatic-update">Automate with CI and AI</a>) only ever installs a newer version within the current major.</p><h2 id="gsds-script-and-gsds-style" tabindex="-1"><code>gsds script</code> and <code>gsds style</code> <a class="header-anchor" href="#gsds-script-and-gsds-style" aria-label="Permalink to &quot;`gsds script` and `gsds style`&quot;">​</a></h2><p>Manage sitewide scripts and stylesheets. Both commands share the same subcommand shape.</p><h3 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>new &lt;slug&gt;</code></td><td>Scaffold a local file and register it</td></tr><tr><td><code>link &lt;url&gt;</code></td><td>Register an external hosted URL. Must end in <code>.js</code> for scripts, <code>.css</code> for stylesheets — the extension is matched case-insensitively</td></tr><tr><td><code>ls</code></td><td>List registered entries</td></tr><tr><td><code>rm &lt;slug&gt;</code></td><td>Remove an entry</td></tr></tbody></table><h3 id="flags-on-new-and-link" tabindex="-1">Flags on <code>new</code> and <code>link</code> <a class="header-anchor" href="#flags-on-new-and-link" aria-label="Permalink to &quot;Flags on `new` and `link`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Applies to</th><th>Description</th></tr></thead><tbody><tr><td><code>--attr k=v</code></td><td>Both</td><td>HTML attribute on the injected tag. Repeatable. Pass a bare <code>--attr defer</code> for a valueless attribute; an empty name (<code>--attr =v</code>) is rejected</td></tr><tr><td><code>--page &lt;name&gt;</code></td><td>Both</td><td>Scope injection to a single page instead of sitewide. Repeatable; identical values collapse to one rule</td></tr><tr><td><code>--placement head|bodyStart|bodyEnd</code></td><td>Scripts only</td><td>Where to inject the script tag</td></tr><tr><td><code>--name &lt;slug&gt;</code></td><td><code>link</code> only</td><td>Explicit slug. When omitted, the slug is derived from the URL</td></tr></tbody></table><h3 id="flags-on-rm" tabindex="-1">Flags on <code>rm</code> <a class="header-anchor" href="#flags-on-rm" aria-label="Permalink to &quot;Flags on `rm`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Delete a folder that is not empty</td></tr></tbody></table><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Print the installed CLI version and exit</td></tr></tbody></table><p><code>gsds</code> with no arguments prints help on stdout and exits <code>0</code>. <code>gsds help &lt;command&gt; &lt;subcommand&gt;</code> resolves to any depth, so <code>gsds help script new</code> shows the help for <code>new</code> rather than for <code>script</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session model and profiles → <a href="./../authenticate.html">Authenticate</a></li><li>Shared dependency deduplication → <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a></li><li>On-disk files → <a href="./project-files.html">Project files</a></li><li>Error messages → <a href="./troubleshooting.html">Troubleshooting</a></li></ul>',82)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
